def _post_present(self, tenant: str, credential_id: str) -> None:
    # 请求体必须恰为 {"disclose": [...]} 加可选 challenge、
    # expires_in：缺失 disclose、类型非法、重复路径或祖先重叠、
    # 多余字段一律 400；未知凭证 404；空列表表示零披露。
    # challenge 须为非空字符串且按 Unicode 码点不超过 256，
    # 缺省生成 32 位小写 hex；expires_in 须为非布尔整数且
    # 在 1..86400 之间，缺省 300。成功 201 返回演示记录。
    data = self._read_json()
    if "disclose" not in data:
        raise ValidationError("缺少字段: disclose")
    extra = sorted(
        set(data)
        - {"disclose", "challenge", "expires_in", "holder_binding"}
    )
    if extra:
        raise ValidationError(f"多余字段: {', '.join(extra)}")
    challenge = None
    if "challenge" in data:
        challenge = data["challenge"]
        if not isinstance(challenge, str) or not challenge:
            raise ValidationError("字段 challenge 必须为非空字符串")
        if len(challenge) > 256:
            raise ValidationError(
                "字段 challenge 按 Unicode 码点不能超过 256"
            )
    expires_in = None
    if "expires_in" in data:
        expires_in = data["expires_in"]
        if not isinstance(expires_in, int) or isinstance(
            expires_in, bool
        ):
            raise ValidationError("字段 expires_in 必须为整数")
        if not 1 <= expires_in <= 86400:
            raise ValidationError(
                "字段 expires_in 须在 1 到 86400 之间"
            )
    # holder_binding 可选：必须为布尔，缺省 false；为 true 时
    # subject_did 须是本租户已注册 DID（否则由 store 判 400）。
    holder_binding = False
    if "holder_binding" in data:
        holder_binding = data["holder_binding"]
        if not isinstance(holder_binding, bool):
            raise ValidationError("字段 holder_binding 必须为布尔值")
    record = store.create_presentation(
        tenant,
        credential_id,
        data["disclose"],
        challenge=challenge,
        expires_in=expires_in,
        holder_binding=holder_binding,
    )
    self._send_json(201, self._presentation_payload(record))

def _post_present_batch(
    self, tenant: str, credential_id: str
) -> None:
    # 批量选择性披露演示：请求体须恰为
    # {"presentations": [项...]}，数组非空且不超过 50 项。
    # 外层缺失/非数组/空/超限、项非对象、缺 disclose 或多余
    # 字段、challenge/expires_in/holder_binding 类型或范围非法
    # 一律 400 且不写入任何记录；路径凭证未知（含他租户）404；
    # 任一项在 store 内失败（disclose 越界/重复/祖先重叠、绑定
    # subject 非本租户 DID、密钥吊销等）整体回滚，已构建项与
    # 审计均不落盘。成功 201 返回 {"presentations": [...]}，
    # 与输入等长、同序，项键序与单项 present 完全一致。
    data = self._read_json()
    if "presentations" not in data:
        raise ValidationError("缺少字段: presentations")
    extra = sorted(set(data) - {"presentations"})
    if extra:
        raise ValidationError(f"多余字段: {', '.join(extra)}")
    items = data["presentations"]
    if not isinstance(items, list):
        raise ValidationError("字段 presentations 必须为数组")
    if not items:
        raise ValidationError("presentations 数组不能为空")
    if len(items) > 50:
        raise ValidationError(
            "presentations 数组不能超过 50 项"
            f"（当前 {len(items)} 项）"
        )
    kwargs_list = [
        self._validate_present_item(item, index)
        for index, item in enumerate(items)
    ]
    records = store.create_presentations_batch(
        tenant, credential_id, kwargs_list
    )
    self._send_json(
        201,
        {
            "presentations": [
                self._presentation_payload(record)
                for record in records
            ]
        },
    )

def _post_verify_presentation(
    self, tenant: str, presentation_id: str
) -> None:
    # 与凭证 verify 相同的公开错误协议：任何“验签失败”都返回
    # 200 + {"valid": false, "reason": "<非空中文原因>"}，绝不
    # 返回 404/500。
    try:
        length = int(self.headers.get("Content-Length") or 0)
        raw = self.rfile.read(length) if length > 0 else b""
    except (ValueError, TypeError):
        self._send_invalid("请求体缺失或长度声明非法")
        return
    except Exception:  # noqa: BLE001
        self._send_invalid("请求体读取失败")
        return
    if not raw:
        self._send_invalid("请求体缺失")
        return
    try:
        data = json.loads(raw.decode("utf-8"))
    except UnicodeDecodeError:
        self._send_invalid("请求体不是合法 UTF-8 文本")
        return
    except json.JSONDecodeError:
        self._send_invalid("请求体不是合法 JSON")
        return
    if not isinstance(data, dict):
        self._send_invalid("请求体必须为 JSON 对象")
        return
    if "presentation" not in data:
        self._send_invalid("请求缺少字段: presentation")
        return
    extra = sorted(set(data) - {"presentation", "challenge"})
    if extra:
        self._send_invalid(f"请求含多余字段: {', '.join(extra)}")
        return
    challenge = CHALLENGE_UNSET
    if "challenge" in data:
        challenge = data["challenge"]
        if not isinstance(challenge, str) or not challenge:
            self._send_invalid(
                "请求字段 challenge 必须为非空字符串"
            )
            return

    try:
        if presentation_id.startswith("mvp_"):
            valid, reason = store.verify_multi_presentation(
                tenant, presentation_id, data["presentation"],
                challenge,
            )
        else:
            valid, reason = store.verify_presentation(
                tenant, presentation_id, data["presentation"], challenge
            )
    except Exception:  # noqa: BLE001 验签失败绝不暴露内部细节
        self._send_invalid("验签过程发生内部错误")
        return
    payload: Dict[str, Any] = {"valid": valid}
    if not valid:
        payload["reason"] = reason or "验签失败"
    self._send_json(200, payload)

@staticmethod
def _multi_presentation_payload(
    record: MultiPresentationRecord,
) -> Dict[str, Any]:
    """按对外契约的固定键序组装多凭证组合展示对象。"""
    payload: Dict[str, Any] = {
        "presentation_id": record.presentation_id,
        "items": [
            {
                "credential_id": item.credential_id,
                "issuer_did": item.issuer_did,
                "issuer_key_version": item.issuer_key_version,
                "disclose": item.disclose,
                "claims": item.projection,
                "proof": item.proof,
            }
            for item in record.items
        ],
        "challenge": record.challenge,
        "expires_at": record.expires_at,
    }
    if record.holder_did is not None:
        payload["holder_did"] = record.holder_did
        payload["holder_key_version"] = record.holder_key_version
        payload["holder_proof"] = record.holder_proof
    return payload

def _post_multi_presentations(self, tenant: str) -> None:
    # 多凭证原子组合展示：请求体恰为 {"items": [项...]} 加可选
    # challenge、expires_in、holder_binding（组合级统一字段）。
    # items 须为非空且不超过 100 项的数组；每项恰含非空字符串
    # credential_id 与 disclose，批内 credential_id 不得重复；
    # disclose 规则同单项 present（RFC6901 claims 叶子：拒根
    # 路径、越界、重复与嵌套覆盖），语义在 store 内结合凭证
    # claims 校验。challenge 非空串按码点 ≤256、缺省 32 位小写
    # hex；expires_in 非布尔整数 1..86400、缺省 300；
    # holder_binding 布尔、缺省 false，绑定时各凭证 subject_did
    # 须一致且为本租户已注册 DID。外层/项结构、挑战、期限、
    # 绑定类型错误一律 400；任一凭证未知或跨租户 404；签发者
    # 停用/凭证暂停 409。成功 201 返回组合展示对象。
    data = self._read_json()
    if "items" not in data:
        raise ValidationError("缺少字段: items")
    extra = sorted(
        set(data)
        - {"items", "challenge", "expires_in", "holder_binding"}
    )
    if extra:
        raise ValidationError(f"多余字段: {', '.join(extra)}")
    items = data["items"]
    if not isinstance(items, list):
        raise ValidationError("字段 items 必须为数组")
    if not items:
        raise ValidationError("items 数组不能为空")
    if len(items) > 100:
        raise ValidationError(
            "items 数组不能超过 100 项"
            f"（当前 {len(items)} 项）"
        )
    request_items: List[Dict[str, Any]] = []
    seen_credential_ids = set()
    for index, item in enumerate(items):
        where = f"第 {index + 1} 项"
        if not isinstance(item, dict):
            raise ValidationError(f"{where}必须为 JSON 对象")
        item_extra = sorted(set(item) - {"credential_id", "disclose"})
        if item_extra:
            raise ValidationError(
                f"{where}含多余字段: {', '.join(item_extra)}"
            )
        if "credential_id" not in item:
            raise ValidationError(f"{where}缺少字段: credential_id")
        if "disclose" not in item:
            raise ValidationError(f"{where}缺少字段: disclose")
        credential_id = item["credential_id"]
        if (
            not isinstance(credential_id, str)
            or not credential_id
        ):
            raise ValidationError(
                f"{where}字段 credential_id 必须为非空字符串"
            )
        if credential_id in seen_credential_ids:
            raise ValidationError(
                f"items 中 credential_id 重复: {credential_id}"
            )
        seen_credential_ids.add(credential_id)
        if not isinstance(item["disclose"], list):
            raise ValidationError(
                f"{where}字段 disclose 必须为数组"
            )
        request_items.append(
            {"credential_id": credential_id, "disclose": item["disclose"]}
        )
    challenge = None
    if "challenge" in data:
        challenge = data["challenge"]
        if not isinstance(challenge, str) or not challenge:
            raise ValidationError("字段 challenge 必须为非空字符串")
        if len(challenge) > 256:
            raise ValidationError(
                "字段 challenge 按 Unicode 码点不能超过 256"
            )
    expires_in = None
    if "expires_in" in data:
        expires_in = data["expires_in"]
        if not isinstance(expires_in, int) or isinstance(
            expires_in, bool
        ):
            raise ValidationError("字段 expires_in 必须为整数")
        if not 1 <= expires_in <= 86400:
            raise ValidationError(
                "字段 expires_in 须在 1 到 86400 之间"
            )
    holder_binding = False
    if "holder_binding" in data:
        holder_binding = data["holder_binding"]
        if not isinstance(holder_binding, bool):
            raise ValidationError("字段 holder_binding 必须为布尔值")
    record = store.create_multi_presentation(
        tenant,
        request_items,
        challenge=challenge,
        expires_in=expires_in,
        holder_binding=holder_binding,
    )
    self._send_json(201, self._multi_presentation_payload(record))

# ------------------------------------------------------------ #
# 谓词证明
# ------------------------------------------------------------ #
def _post_prove(self, tenant: str, credential_id: str) -> None:
    # 请求体必须恰为 {"predicates": [...]} 加可选 challenge、
    # expires_in：缺失/空 predicates、元素字段或 op 非法、路径
    # 重复或祖先重叠、多余字段一律 400；未知凭证 404。
    # challenge 须为非空字符串且按 Unicode 码点不超过 256，
    # 缺省生成 32 位小写 hex；expires_in 须为非布尔整数且
    # 在 1..86400 之间，缺省 300。成功 201 返回证明记录。
    data = self._read_json()
    if "predicates" not in data:
        raise ValidationError("缺少字段: predicates")
    extra = sorted(set(data) - {"predicates", "challenge", "expires_in"})
    if extra:
        raise ValidationError(f"多余字段: {', '.join(extra)}")
    challenge = None
    if "challenge" in data:
        challenge = data["challenge"]
        if not isinstance(challenge, str) or not challenge:
            raise ValidationError("字段 challenge 必须为非空字符串")
        if len(challenge) > 256:
            raise ValidationError(
                "字段 challenge 按 Unicode 码点不能超过 256"
            )
    expires_in = None
    if "expires_in" in data:
        expires_in = data["expires_in"]
        if not isinstance(expires_in, int) or isinstance(
            expires_in, bool
        ):
            raise ValidationError("字段 expires_in 必须为整数")
        if not 1 <= expires_in <= 86400:
            raise ValidationError(
                "字段 expires_in 须在 1 到 86400 之间"
            )
    record = store.create_proof(
        tenant,
        credential_id,
        data["predicates"],
        challenge=challenge,
        expires_in=expires_in,
    )
    self._send_json(201, self._proof_payload(record))

@staticmethod
def _proof_payload(record: Any) -> Dict[str, Any]:
    return {
        "proof_id": record.proof_id,
        "credential_id": record.credential_id,
        "issuer_did": record.issuer_did,
        "issuer_key_version": record.issuer_key_version,
        "predicates": record.predicates,
        "results": record.results,
        "challenge": record.challenge,
        "expires_at": record.expires_at,
        "proof": record.proof,
    }

@staticmethod
def _validate_prove_item(
    item: Any, index: int
) -> Dict[str, Any]:
    """校验单个谓词证明生成项，返回透传给 store 的关键字参数。

    规则与单项 prove 的请求级校验完全一致：项须为对象，恰含
    predicates 及可选 challenge、expires_in；challenge 为非空
    字符串且按 Unicode 码点不超过 256；expires_in 为非布尔整数
    且在 1..86400。predicates 的结构、路径、运算与数值语义在
    store 内结合凭证 claims 校验，与单项 prove 完全一致。
    index 为从 0 起的项序号，错误信息带从 1 起的中文项号。
    """
    where = f"第 {index + 1} 项"
    if not isinstance(item, dict):
        raise ValidationError(f"{where}必须为 JSON 对象")
    if "predicates" not in item:
        raise ValidationError(f"{where}缺少字段: predicates")
    extra = sorted(
        set(item) - {"predicates", "challenge", "expires_in"}
    )
    if extra:
        raise ValidationError(
            f"{where}含多余字段: {', '.join(extra)}"
        )
    kwargs: Dict[str, Any] = {"predicates": item["predicates"]}
    if "challenge" in item:
        challenge = item["challenge"]
        if not isinstance(challenge, str) or not challenge:
            raise ValidationError(
                f"{where}字段 challenge 必须为非空字符串"
            )
        if len(challenge) > 256:
            raise ValidationError(
                f"{where}字段 challenge 按 Unicode 码点不能超过 256"
            )
        kwargs["challenge"] = challenge
    if "expires_in" in item:
        expires_in = item["expires_in"]
        if not isinstance(expires_in, int) or isinstance(
            expires_in, bool
        ):
            raise ValidationError(
                f"{where}字段 expires_in 必须为整数"
            )
        if not 1 <= expires_in <= 86400:
            raise ValidationError(
                f"{where}字段 expires_in 须在 1 到 86400 之间"
            )
        kwargs["expires_in"] = expires_in
    return kwargs

def _post_prove_batch(
    self, tenant: str, credential_id: str
) -> None:
    # 批量谓词证明：请求体须恰为 {"items": [项...]}，数组非空
    # 且不超过 50 项。外层缺失/非数组/空/超限、项非对象、缺
    # predicates 或多余字段、challenge/expires_in 类型或范围非法
    # 一律 400 且不写入任何记录；所有项的请求级校验全部通过后
    # 才查凭证：路径凭证未知（含他租户）404；其后按签发 DID
    # 停用 409、签发密钥吊销 400、凭证暂停 409 的顺序拒绝，
    # 均不留证明或审计；项内 predicates 语义（结构/路径/运算/
    # 数值、重复与祖先重叠）由 store 逐项校验，任一失败整体
    # 回滚。成功 201 仅返回 {"proofs": [...]}，与输入等长、同序，
    # 每项键序与单项 prove 完全一致；缺省 challenge 与有效期逐项
    # 独立生成。全部证明记录与每条 proof.created 审计同一次原子
    # 提交，落盘失败 500 且不留下部分记录，审计序号不前进。
    data = self._read_json()
    if "items" not in data:
        raise ValidationError("缺少字段: items")
    extra = sorted(set(data) - {"items"})
    if extra:

        holder_version_value = int(
            row.get("holder_key_version", 0)
        )
        holder_public_pem = self._public_key_for_version_locked(
            bucket, holder_did_value, holder_version_value
        )
        holder_entry = self._key_history_entry_by_version_locked(
            bucket, holder_did_value, holder_version_value
        )
        holder_key_revoked = (
            holder_entry is not None
            and holder_entry.get("status") == "revoked"
        )
        holder_key_revoke_reason = (
            holder_entry.get("revoke_reason")
            if holder_entry is not None
            else None
        )

# 按存储的 disclose 从存储凭证 claims 重算投影并核对
stored_disclose = list(row.get("disclose", []))
try:
    parsed_stored = [
        (pointer, _parse_pointer(pointer))
        for pointer in stored_disclose
    ]
    recomputed = _project_claims(source_claims, parsed_stored)
except ValidationError as exc:
    return False, f"投影重算失败: {exc}"
if obj_claims != recomputed:
    return False, (
        "锚定校验失败: claims 投影与按存储凭证重算的结果不一致"
    )

if not public_pem:
    return False, (
        "历史公钥不可用: 签发者 "
        f"{issuer_did} 密钥版本 {stored_version} 的公钥不存在"
    )
try:
    crypto.validate_public_key_pem(public_pem)
except (ValueError, TypeError):
    return False, (
        "历史公钥不可用: 签发者 "
        f"{issuer_did} 密钥版本 {stored_version} 的公钥无法解析"
    )

unsigned = {
    "presentation_id": presentation_id,
    "credential_id": credential_id,
    "issuer_did": issuer_did,
    "issuer_key_version": stored_version,
    "disclose": list(row.get("disclose", [])),
    "claims": recomputed,
}
if is_replay_protected:
    unsigned["challenge"] = row.get("challenge")
    unsigned["expires_at"] = row.get("expires_at")
try:
    crypto.verify(unsigned, proof, public_pem)
except crypto.MalformedSignature:
    return False, "签名格式错误: 不是合法的 ES256 签名编码"
except crypto.InvalidSignature:
    return False, "签名校验失败，演示内容或 proof 可能被改动"
except Exception:  # noqa: BLE001 验签绝不向上抛错或泄露内部细节
    return False, "验签过程发生内部错误"

# issuer proof 验签成功后检查签发密钥版本是否已吊销（优先于
# 持有者校验、凭证有效期与凭证吊销）。
if issuer_key_revoked:
    saved_reason = (
        issuer_key_revoke_reason or DEFAULT_KEY_REVOKE_REASON
    )
    return False, f"签发密钥已吊销：{saved_reason}"

# 双签名锚定的 issuer 侧已通过：签发者 DID 已停用则 valid:false，
# 优先于持有者校验、凭证有效期与凭证吊销（只读，不消费）。
if issuer_did_deactivated:
    saved_reason = (
        issuer_did_deactivate_reason
        or DEFAULT_DID_DEACTIVATE_REASON
    )
    return False, f"{DID_DEACTIVATED_REASON_PREFIX}{saved_reason}"

if is_holder_bound:
    # 持有者第二签名：覆盖去掉 proof、holder_proof 后的完整演示
    # 对象（此处与 issuer proof 覆盖对象同构，另含 holder_did、
    # holder_key_version）及 tenant_id，按规范化 JSON/UTF-8 验签；
    # 公钥按 holder_key_version 取持有者历史公钥，轮换后仍可验证。
    if not holder_public_pem:
        return False, (
            "历史公钥不可用: 持有者 "
            f"{holder_did_value} 密钥版本 "
            f"{holder_version_value} 的公钥不存在"
        )
    try:
        crypto.validate_public_key_pem(holder_public_pem)
    except (ValueError, TypeError):
        return False, (
            "历史公钥不可用: 持有者 "
            f"{holder_did_value} 密钥版本 "
            f"{holder_version_value} 的公钥无法解析"
        )
    holder_unsigned = dict(unsigned)
    holder_unsigned["holder_did"] = holder_did_value
    holder_unsigned["holder_key_version"] = holder_version_value
    holder_unsigned["tenant_id"] = tenant_id
    try:
        crypto.verify(
            holder_unsigned, holder_proof, holder_public_pem
        )
    except crypto.MalformedSignature:
        return False, (
            "签名格式错误: holder_proof 不是合法的 ES256 签名编码"
        )
    except crypto.InvalidSignature:
        return False, (
            "签名校验失败: holder_proof 与持有者历史公钥不匹配，"
            "持有者绑定内容可能被改动"
        )
    except Exception:  # noqa: BLE001 验签绝不向上抛错
        return False, "验签过程发生内部错误"

    # 持有者 proof 验签成功后检查持有者密钥版本是否已吊销
    # （优先于凭证有效期与凭证吊销）。
    if holder_key_revoked:
        saved_reason = (
            holder_key_revoke_reason or DEFAULT_KEY_REVOKE_REASON
        )
        return False, f"持有者密钥已吊销：{saved_reason}"

# 签名与锚定均成功后检查凭证有效期：凭证已到期直接拒绝，不消费
if _is_expired(credential_expires_at):
    return False, CREDENTIAL_EXPIRED_REASON

# 签名与锚定均成功后检查凭证状态：已暂停/已吊销不消费，判定
# 位置相同（有效期之后、消费之前）；暂停返回保存的暂停原因，
# 恢复后可再次正常使用。
if credential_status == "suspended":
    saved_reason = suspend_reason or "未知原因"
    return False, f"{CREDENTIAL_SUSPENDED_REASON_PREFIX}{saved_reason}"
if credential_status == "revoked":
    saved_reason = revoke_reason or DEFAULT_REVOKE_REASON
    return False, f"凭证已吊销：{saved_reason}"

if is_replay_protected:
    # 原子标记已消费：消费锁内复查已消费/到期/吊销，防止
    # “锁外验签期间演示到期仍被消费”的竞态。并发仅一次成功，
    # 跨重启保留；复查到期或已吊销均不消费、不记审计。
    with self._lock:
        bucket = self._bucket_locked(tenant_id)
        row = (
            bucket["presentations"].get(presentation_id)
            if bucket is not None else None
        )
        if row is None:
            return False, f"演示不存在: {presentation_id}"
        if row.get("consumed"):
            return False, "演示已消费"
        try:
            expires_at = _parse_utc_z(row["expires_at"])
        except (KeyError, TypeError, ValueError):
            return False, "验签过程发生内部错误"
        if datetime.now(timezone.utc) >= expires_at:
            return False, "演示已过期"
        cred = bucket["credentials"].get(credential_id)
        # 锁内复查密钥版本吊销状态（防锁外验签期间被吊销的竞态）：
        # 签发密钥优先于持有者密钥，二者均优先于凭证有效期/吊销。
        issuer_entry_now = self._key_history_entry_by_version_locked(
            bucket, issuer_did, stored_version
        )
        if (
            issuer_entry_now is not None
            and issuer_entry_now.get("status") == "revoked"
        ):
            saved_reason = (
                issuer_entry_now.get("revoke_reason")
                or DEFAULT_KEY_REVOKE_REASON
            )
            return False, f"签发密钥已吊销：{saved_reason}"
        # 锁内复查签发者 DID 停用状态（防锁外验签期间被停用的
        # 竞态）：停用不消费，优先于有效期/凭证吊销。
        issuer_row_now = bucket["dids"].get(issuer_did)
        if self._is_did_deactivated_locked(issuer_row_now):
            saved_reason = (
                issuer_row_now.get("deactivate_reason")
                or DEFAULT_DID_DEACTIVATE_REASON
            )
            return False, (
                f"{DID_DEACTIVATED_REASON_PREFIX}{saved_reason}"
            )
        if is_holder_bound and holder_did_value is not None:
            holder_entry_now = (
                self._key_history_entry_by_version_locked(
                    bucket,
                    holder_did_value,
                    holder_version_value,
                )
            )
            if (
                holder_entry_now is not None
                and holder_entry_now.get("status") == "revoked"
            ):
                saved_reason = (
                    holder_entry_now.get("revoke_reason")
                    or DEFAULT_KEY_REVOKE_REASON
                )
                return False, f"持有者密钥已吊销：{saved_reason}"
        if cred is not None and _is_expired(
            cred["body"].get("expires_at")
        ):
            return False, CREDENTIAL_EXPIRED_REASON
        if cred is not None and cred.get("status") == "suspended":
            saved_reason = (
                cred.get("suspend_reason") or "未知原因"
            )
            return False, f"{CREDENTIAL_SUSPENDED_REASON_PREFIX}{saved_reason}"
        if cred is not None and cred.get("status") == "revoked":
            saved_reason = (
                cred.get("revoke_reason") or DEFAULT_REVOKE_REASON

    payload: Dict[str, Any] = {"valid": valid}
    if not valid:
        payload["reason"] = reason or "验签失败"
    self._send_json(200, payload)

@staticmethod
def _presentation_payload(
    record: PresentationRecord,
) -> Dict[str, Any]:
    """按对外契约的固定键序组装演示对象。

    未绑定恰为九字段；持有者绑定在末尾追加 holder_did、
    holder_key_version、holder_proof。
    """
    payload: Dict[str, Any] = {
        "presentation_id": record.presentation_id,
        "credential_id": record.credential_id,
        "issuer_did": record.issuer_did,
        "issuer_key_version": record.issuer_key_version,
        "disclose": record.disclose,
        "claims": record.projection,
        "challenge": record.challenge,
        "expires_at": record.expires_at,
        "proof": record.proof,
    }
    # 仅持有者绑定演示返回 holder_did、holder_key_version、
    # holder_proof；未绑定响应字段集合与旧流程完全一致。
    if record.holder_did is not None:
        payload["holder_did"] = record.holder_did
        payload["holder_key_version"] = (
            record.holder_key_version
        )
        payload["holder_proof"] = record.holder_proof
    return payload

@staticmethod
def _validate_present_item(
    item: Any, index: int
) -> Dict[str, Any]:
    """校验单个演示生成项，返回透传给 store 的关键字参数。

    规则与单项 present 完全一致：项须为对象，恰含 disclose 及
    可选 challenge、expires_in、holder_binding；challenge 为非空
    字符串且按 Unicode 码点不超过 256；expires_in 为非布尔整数
    且在 1..86400；holder_binding 为布尔。index 为从 0 起的项
    序号，错误信息带从 1 起的中文项号。
    """
    where = f"第 {index + 1} 项"
    if not isinstance(item, dict):
        raise ValidationError(f"{where}必须为 JSON 对象")
    if "disclose" not in item:
        raise ValidationError(f"{where}缺少字段: disclose")
    extra = sorted(
        set(item)
        - {"disclose", "challenge", "expires_in", "holder_binding"}
    )
    if extra:
        raise ValidationError(
            f"{where}含多余字段: {', '.join(extra)}"
        )
    kwargs: Dict[str, Any] = {"disclose": item["disclose"]}
    if "challenge" in item:
        challenge = item["challenge"]
        if not isinstance(challenge, str) or not challenge:
            raise ValidationError(
                f"{where}字段 challenge 必须为非空字符串"
            )
        if len(challenge) > 256:
            raise ValidationError(
                f"{where}字段 challenge 按 Unicode 码点不能超过 256"
            )
        kwargs["challenge"] = challenge
    if "expires_in" in item:
        expires_in = item["expires_in"]
        if not isinstance(expires_in, int) or isinstance(
            expires_in, bool
        ):
            raise ValidationError(
                f"{where}字段 expires_in 必须为整数"
            )
        if not 1 <= expires_in <= 86400:
            raise ValidationError(
                f"{where}字段 expires_in 须在 1 到 86400 之间"
            )
        kwargs["expires_in"] = expires_in
    if "holder_binding" in item:
        holder_binding = item["holder_binding"]
        if not isinstance(holder_binding, bool):
            raise ValidationError(
                f"{where}字段 holder_binding 必须为布尔值"
            )
        kwargs["holder_binding"] = holder_binding
    return kwargs

def _post_present(self, tenant: str, credential_id: str) -> None:
    # 请求体必须恰为 {"disclose": [...]} 加可选 challenge、
    # expires_in：缺失 disclose、类型非法、重复路径或祖先重叠、
    # 多余字段一律 400；未知凭证 404；空列表表示零披露。
    # challenge 须为非空字符串且按 Unicode 码点不超过 256，
    # 缺省生成 32 位小写 hex；expires_in 须为非布尔整数且

def build_handler(store: VCStore) -> type:
    """构造绑定给定 store 的请求处理器类。"""

    class Handler(BaseHTTPRequestHandler):
        server_version = "VCBackend/0.1"

        # ------------------------------------------------------------ #
        # 响应工具
        # ------------------------------------------------------------ #
        def _send_json(self, status: int, payload: Any) -> None:
            body = _json_dumps(payload)
            self.send_response(status)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def _send_error(self, status: int, message: str) -> None:
            self._send_json(status, {"error": message})

        def _send_invalid(self, reason: str) -> None:
            """verify 端点统一失败响应：HTTP 200 + valid:false + 中文原因。"""
            self._send_json(200, {"valid": False, "reason": reason})

        def _tenant_id(self) -> str:
            """解析 X-Tenant-ID：缺省 default；显式空串 400。"""
            raw = self.headers.get("X-Tenant-ID")
            if raw is None:
                return DEFAULT_TENANT
            if raw == "":
                raise ValidationError("X-Tenant-ID 不能为空")
            return raw

        def _read_json(self) -> Dict[str, Any]:
            length = int(self.headers.get("Content-Length") or 0)
            raw = self.rfile.read(length) if length else b""
            try:
                data = json.loads(raw.decode("utf-8")) if raw else None
            except (UnicodeDecodeError, json.JSONDecodeError) as exc:
                raise ValidationError(f"请求体不是合法 JSON: {exc}") from exc
            if not isinstance(data, dict):
                raise ValidationError("请求体必须为 JSON 对象")
            return data

        def _read_optional_json(self) -> Dict[str, Any]:
            """读取可选请求体：空体等价于 {}，非空时须为 JSON 对象。"""
            length = int(self.headers.get("Content-Length") or 0)
            raw = self.rfile.read(length) if length else b""
            if not raw:
                return {}
            try:
                data = json.loads(raw.decode("utf-8"))
            except (UnicodeDecodeError, json.JSONDecodeError) as exc:
                raise ValidationError(f"请求体不是合法 JSON: {exc}") from exc
            if not isinstance(data, dict):
                raise ValidationError("请求体必须为 JSON 对象")
            return data

        # ------------------------------------------------------------ #
        # 路由
        # ------------------------------------------------------------ #
        def do_POST(self) -> None:  # noqa: N802 (BaseHTTPRequestHandler API)
            try:
                parsed = urlparse(self.path)
                path = parsed.path.rstrip("/") or "/"
                parsed_query = parsed.query
                if not path.startswith("/v1"):
                    self._send_error(404, f"无此路径: {path}")
                    return
                # 凭证状态回执消费（单条与批量）及凭证状态回执消费同步
                # 进度回执消费协议：显式空 X-Tenant-ID 一律 400 且仅
                # {"error": "请求非法"}（区别于其余入口的
                # “X-Tenant-ID 不能为空”）。
                if (
                    path
                    in (
                        "/v1/trust/credential-status/receipt/consume",
                        "/v1/trust/credential-status/receipt/consume-batch",
                        "/v1/trust/credential-status/receipt-sync"
                        "/receipt/consume",
                        "/v1/trust/credential-status/receipt-sync"
                        "/receipt/consume-batch",
                        "/v1/trust/credentials/imported/verify-batch",
                        "/v1/audit/manifest/verify-batch",
                    )
                    and self.headers.get("X-Tenant-ID") == ""
                ):
                    raise ValidationError("请求非法")
                tenant = self._tenant_id()
                if path == "/v1/dids":
                    self._post_dids(tenant)
                elif path == "/v1/audit/manifest/verify":
                    self._post_audit_manifest_verify(tenant)
                elif path == "/v1/audit/manifest/verify-batch":
                    self._post_audit_manifest_verify_batch(tenant)
                elif path == "/v1/credentials":
                    self._post_credentials(tenant)
                elif path == "/v1/credential-schemas":
                    self._post_credential_schemas(tenant)
                elif path.startswith("/v1/credential-schemas/") and path.endswith(
                    "/status"
                ):
                    self._post_credential_schema_status(
                        tenant,
                        path[
                            len("/v1/credential-schemas/") : -len("/status")
                        ],
                    )
                elif path == "/v1/credentials/status-export":
                    self._post_credentials_status_export(tenant)
                elif path == "/v1/credentials/revoke-batch":
                    self._post_revoke_credentials_batch(tenant)
                elif path.startswith("/v1/dids/") and path.endswith(
                    "/keys/rotate"
                ):
                    did = unquote(
                        path[len("/v1/dids/") : -len("/keys/rotate")]
                    )
                    self._post_rotate_key(tenant, did)
                elif path.startswith("/v1/dids/") and "/keys/" in path and path.endswith(
                    "/revoke"
                ):
                    middle = path[len("/v1/dids/") : -len("/revoke")]
                    did_raw, sep, version_raw = middle.partition("/keys/")
                    did = unquote(did_raw)
                    key_version = unquote(version_raw) if sep else ""
                    self._post_revoke_key(tenant, did, key_version)
                elif path.startswith("/v1/dids/") and path.endswith(
                    "/deactivate"
                ):
                    did = unquote(
                        path[len("/v1/dids/") : -len("/deactivate")]
                    )
                    self._post_deactivate_did(tenant, did)
                elif path.startswith("/v1/credentials/") and path.endswith(
                    "/revoke"
                ):
                    credential_id = unquote(
                        path[len("/v1/credentials/") : -len("/revoke")]
                    )
                    self._post_revoke_credential(tenant, credential_id)
                elif path.startswith("/v1/credentials/") and path.endswith(
                    "/verify"
                ):
                    credential_id = unquote(
                        path[len("/v1/credentials/") : -len("/verify")]
                    )
                    self._post_verify_credential(
                        tenant, credential_id
                    )
                elif path.startswith("/v1/credentials/") and path.endswith(
                    "/present"
                ):
                    credential_id = unquote(
                        path[len("/v1/credentials/") : -len("/present")]
                    )
                    self._post_present(tenant, credential_id)
                elif path.startswith("/v1/credentials/") and path.endswith(
                    "/present-batch"
                ):
                    credential_id = unquote(
                        path[len("/v1/credentials/") : -len("/present-batch")]
                    )
                    self._post_present_batch(tenant, credential_id)
                elif path.startswith("/v1/credentials/") and path.endswith(
                    "/prove"
                ):
                    credential_id = unquote(
                        path[len("/v1/credentials/") : -len("/prove")]
                    )
                    self._post_prove(tenant, credential_id)
                elif path.startswith("/v1/credentials/") and path.endswith(
                    "/prove-batch"
                ):
                    credential_id = unquote(
                        path[len("/v1/credentials/") : -len("/prove-batch")]
                    )
                    self._post_prove_batch(tenant, credential_id)
                elif path.startswith("/v1/proofs/") and path.endswith(
                    "/verify"

            == "/v1/trust/credential-status/receipt-sync/receipt"
            "/consumptions/manifest/verify-batch"
        ):
            self._post_trust_credential_status_receipt_sync_receipt_consumptions_manifest_verify_batch(
                tenant
            )
        elif (
            path
            == "/v1/trust/credential-status/receipt-sync-batch"
        ):
            self._post_trust_credential_status_receipt_sync_batch(
                tenant
            )
        else:
            self._send_error(404, f"无此路径: {path}")
    except ValidationError as exc:
        self._send_error(400, str(exc))
    except ConflictError as exc:
        self._send_error(409, str(exc))
    except NotFoundError as exc:
        self._send_error(404, str(exc))
    except Exception as exc:  # noqa: BLE001
        self._send_error(500, f"服务器内部错误: {exc}")

def do_PUT(self) -> None:  # noqa: N802
    try:
        path = urlparse(self.path).path.rstrip("/") or "/"
        if not path.startswith("/v1"):
            self._send_error(404, f"无此路径: {path}")
            return
        tenant = self._tenant_id()
        if path.startswith("/v1/credentials/") and path.endswith(
            "/status"
        ):
            credential_id = unquote(
                path[len("/v1/credentials/") : -len("/status")]
            )
            self._put_credential_status(tenant, credential_id)
        elif path.startswith("/v1/trust/anchors/") and path.endswith(
            "/status"
        ):
            rest = path[len("/v1/trust/anchors/") : -len("/status")]
            did, sep, version_raw = rest.rpartition("/")
            if not sep or not did:
                self._send_error(404, f"无此路径: {path}")
            else:
                self._put_trust_anchor_status(
                    tenant, unquote(did), unquote(version_raw)
                )
        elif path.startswith("/v1/trust/anchors/") and path.endswith(
            "/uses"
        ):
            rest = path[len("/v1/trust/anchors/") : -len("/uses")]
            did, sep, version_raw = rest.rpartition("/")
            if not sep or not did:
                self._send_error(404, f"无此路径: {path}")
            else:
                self._put_trust_anchor_uses(
                    tenant, unquote(did), unquote(version_raw)
                )
        else:
            self._send_error(404, f"无此路径: {path}")
    except ValidationError as exc:
        self._send_error(400, str(exc))
    except ConflictError as exc:
        self._send_error(409, str(exc))
    except NotFoundError as exc:
        self._send_error(404, str(exc))
    except Exception as exc:  # noqa: BLE001
        self._send_error(500, f"服务器内部错误: {exc}")

def do_GET(self) -> None:  # noqa: N802
    try:
        parsed = urlparse(self.path)
        path = parsed.path.rstrip("/") or "/"
        if path in ("/health", "/healthz"):
            self._send_json(200, {"status": "ok"})
            return
        if not path.startswith("/v1"):
            self._send_error(404, f"无此路径: {path}")
            return
        # 仅 /v1 路由受租户头约束
        if (
            path
            == "/v1/trust/presentation-sync/receipt/consumptions"
            and self.headers.get("X-Tenant-ID") == ""
        ):
            raise ValidationError("请求非法")
        tenant = self._tenant_id()
        if path == "/v1/audit":
            self._get_audit(tenant, parsed.query)
        elif path == "/v1/audit/manifest":
            self._get_audit_manifest(tenant, parsed.query)
        elif path.startswith("/v1/dids/") and path.endswith(
            "/document"
        ):
            did = unquote(
                path[len("/v1/dids/") : -len("/document")]
            )
            self._get_did_document(tenant, did, parsed.query)
        elif path.startswith("/v1/dids/") and "/keys/" in path and (
            path.endswith("/status")
            or path.endswith("/keys/revocations")
            or path.endswith("/keys/history")
        ):
            middle = path[len("/v1/dids/") :]
            did_raw, sep, rest = middle.partition("/keys/")
            did = unquote(did_raw)
            if rest == "revocations":
                self._get_key_revocations(
                    tenant, did, parsed.query
                )
            elif rest == "history":
                self._get_key_history(
                    tenant, did, parsed.query
                )
            else:
                key_version = unquote(
                    rest[: -len("/status")]
                )

def _load(self) -> None:
    data: Dict[str, Any] = {}
    if os.path.exists(self.path):
        with open(self.path, "r", encoding="utf-8") as fh:
            data = json.load(fh)
    if isinstance(data.get("tenants"), dict):
        self._tenants = data["tenants"]
    else:
        # 旧版顶层结构：整体迁入 default 租户桶
        legacy: Dict[str, Any] = {}
        for key in ("dids", "credentials", "presentations"):
            if key in data:
                legacy[key] = data[key]
        self._tenants = {DEFAULT_TENANT: legacy} if legacy else {}
    self._audit = list(data.get("audit", []))
    if self._audit:
        self._audit_seq = int(
            data.get("audit_seq", self._audit[-1].get("seq", 0))
        )
    else:
        self._audit_seq = int(data.get("audit_seq", 0))
    for bucket in self._tenants.values():
        bucket.setdefault("dids", {})
        bucket.setdefault("credentials", {})
        # 凭证模式（约束）注册表：
        # issuer_did -> schema_id -> version -> 模式行
        bucket.setdefault("credential_schemas", {})
        # 凭证模式版本生命周期历史：
        # issuer_did -> schema_id -> version -> [事件...]
        bucket.setdefault("credential_schema_history", {})
        bucket.setdefault("presentations", {})
        # 多凭证组合展示记录（与单凭证 presentations 相互独立）
        bucket.setdefault("multi_presentations", {})
        bucket.setdefault("proofs", {})
        bucket.setdefault("trust_anchors", {})
        bucket.setdefault("credential_status_sync", {})
        bucket.setdefault("imported_credentials", {})
        bucket.setdefault("credential_status_history", {})
        bucket.setdefault("key_revocations", {})
        bucket.setdefault("key_lifecycle", {})
        bucket.setdefault("trust_anchor_history", {})
        bucket.setdefault("trust_anchor_uses_history", {})
        bucket.setdefault("local_credential_status_history", {})
        bucket.setdefault("did_history", {})
        bucket.setdefault("did_deactivation_notices", {})
        bucket.setdefault("did_deactivation_events", [])
        bucket.setdefault("trust_anchor_change_events", [])
        bucket.setdefault("consumed_receipts", {})
        bucket.setdefault("receipt_consumption_events", [])
        bucket.setdefault("synced_receipts", {})
        bucket.setdefault("synced_receipt_consumption_events", [])
        # 凭证状态回执消费历史同步（credential-status/receipt-sync）：
        # synced_credential_status_receipts 为租户内 (verifier_did,
        # nonce) 判重索引；..._events 按 signer_did 保存来源导出行原文。
        # 两者与普通验真回执同步相互独立。
        bucket.setdefault("synced_credential_status_receipts", {})
        bucket.setdefault(
            "synced_credential_status_receipt_consumption_events", []
        )
        bucket.setdefault("synced_anchor_change_pages", {})
        # 跨系统外部演示消费历史同步（presentation-sync）落盘内容：
        # synced_trust_presentations 为按租户的 (issuer_did,
        # presentation_id) 判重索引；..._events 按 signer_did 保存
        # 已落盘的来源导出行原文。
        bucket.setdefault("synced_trust_presentations", {})
        bucket.setdefault(
            "synced_trust_presentation_consumption_events", {}
        )
        # 跨系统外部演示一次性消费判重索引：
